import { useState } from 'react'
import { CorpLogo } from "../../asset/image"
import { Link, useLocation } from 'react-router-dom'

const Navbar = (props: { [key: string]: any }) => {

    const { linkShowNavbar } = props;

    // Gather location information
    const location = useLocation()

    // State for opening Navbar
    const [navbar, setNavbar] = useState(false);
    const handleNav = () => {
        setNavbar(!navbar);
    }

    return (
        <div style={{ display: (linkShowNavbar.includes(location.pathname)) ? "flex" : "none" }}>
            <nav style={{height: "60px", maxHeight: "60px", minHeight: "60px", position: "fixed", width: "100dvw", backgroundColor: "white"}} className={`${navbar ? "bg-opacity-80" : "bg-opacity-0"}`}>
                <div className="md:w-full w-full md:px-0 md:pr-5 pr-5 pt-1 mx-auto flex justify-between items-center bg-white bg-opacity-80">
                    <div className="flex justify-center gap-2 items-center">
                        <img alt='logo' src={CorpLogo} className="h-10 my-1 object-contain " />
                        {/* <h1 className="md:text-3xl text-2xl text-center font-black text-sky-900 tracking-wide">
                            REGARDE
                        </h1> */}
                    </div>
                    <div className="lg:flex justify-around  items-center hidden">
                        <Link className={`ml-10 text-lg text-sky-950 ${location.pathname === '/' ? `font-bold border-b-2 border-cyan-500 ` : ``}`} to="/">Home</Link>
                        <Link className={`ml-10 text-lg text-sky-950 ${location.pathname === '/certifications' ? `font-bold border-b-2 border-cyan-500 ` : ``}`} to="/certifications">Certifications</Link>
                        <Link className={`ml-10 text-lg text-sky-950 ${location.pathname === '/virtual-office' ? `font-bold border-b-2 border-cyan-500 ` : ``}`} to="/virtual-office">Virtual Office</Link>
                        <Link className={`ml-10 text-lg text-sky-950 ${location.pathname === '/intellectual-property' ? `font-bold border-b-2 border-cyan-500 ` : ``}`} to="/intellectual-property">Intellectual Property</Link>
                        <Link className={`ml-10 text-lg text-sky-950 ${location.pathname === '/law-firm' ? `font-bold border-b-2 border-cyan-500 ` : ``}`} to="/law-firm">Law Firm</Link>
                        <Link className={`ml-10 text-lg text-sky-950 ${location.pathname === '/advertising' ? `font-bold border-b-2 border-cyan-500 ` : ``}`} to="/advertising">Advertising</Link>
                        <Link className={`ml-10 text-lg text-sky-950 ${location.pathname === '/contact' ? `font-bold border-b-2 border-cyan-500 ` : ``}`} to="/contact">Contact</Link>
                    </div>
                    <div className="lg:hidden z-[9999] relative">
                        <button onClick={handleNav}>
                            {navbar ?
                                (<svg xmlns="http://www.w3.org/2000/svg" className="h-11 w-11 text-sky-950" viewBox="0 0 20 20" fill="currentColor">
                                    <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
                                </svg>)
                                :
                                (<svg xmlns="http://www.w3.org/2000/svg" className="h-11 w-11 text-sky-950" viewBox="0 0 20 20" fill="currentColor">
                                    <path fillRule="evenodd" d="M3 5a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zM3 10a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zM9 15a1 1 0 011-1h6a1 1 0 110 2h-6a1 1 0 01-1-1z" clipRule="evenodd" />
                                </svg>)}
                        </button>
                    </div>
                </div>
                <div className={`w-screen h-screen fixed top-0 left-0 bg-sky-950 bg-opacity-90 transform transition-transform duration-300 ease-in-out z-40 ${navbar ? 'translate-x-0 pointer-events-auto' : 'translate-x-full pointer-events-none'}`}>
                    <div className="font-sans bg-white bg-opacity-90">
                        <ul className="flex-col w-screen h-screen text-center pt-32 justify-around items-center text-xl tracking-wide text-white">
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline" >
                                <Link className={`ml-10 text-lg text-sky-950 ${location.pathname === '/' ? `font-bold border-b-2 border-cyan-500 ` : ``}`} to="/">Home</Link>
                            </li>
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline">
                                <Link className={`ml-10 text-lg text-sky-950 ${location.pathname === '/certifications' ? `font-bold border-b-2 border-cyan-500   ` : ``}`} to="/certifications">Certifications</Link>
                            </li>
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline">
                                <Link className={`ml-10 text-lg text-sky-950 ${location.pathname === '/virtual-office' ? `font-bold border-b-2 border-cyan-500   ` : ``}`} to="/virtual-office">Virtual Office</Link>
                            </li>
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline">
                                <Link className={`ml-10 text-lg text-sky-950 ${location.pathname === '/intellectual-property' ? `font-bold border-b-2 border-cyan-500   ` : ``}`} to="/intellectual-property">Intellectual Property</Link>
                            </li>
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline">
                                <Link className={`ml-10 text-lg text-sky-950 ${location.pathname === '/law-firm' ? `font-bold border-b-2 border-cyan-500   ` : ``}`} to="/law-firm">Law Firm</Link>
                            </li>
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline">
                                <Link className={`ml-10 text-lg text-sky-950 ${location.pathname === '/advertising' ? `font-bold border-b-2 border-cyan-500   ` : ``}`} to="/advertising">Advertising</Link>
                            </li>
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline">
                                <Link className={`ml-10 text-lg text-sky-950 ${location.pathname === '/contact' ? `font-bold border-b-2 border-cyan-500  ` : ``}`} to="/contact">Contact</Link>
                            </li>
                        </ul>
                    </div>

                </div>
            </nav>
        </div>
    )
}

export default Navbar
